"import json\nimport os\n\npath = r\"C:\\Users\\a-6600\\.gemini\\antigravity\\brain\\defefd3d-03a6-48cc-ab0b-1fbc66f83de5\\.system_generated\\logs\\transcript.jsonl\"\nif not os.path.exists(path):\n    print(\"Transcript not found at\", path)\n    exit(1)\n\nwith open(path, \"r\", encoding=\"utf-8\") as f:\n    for idx, line in enumerate(f):\n        if \"implementation_plan.md\" in line:\n            obj = json.loads(line)\n            # Find the write_to_file or replace_file_content tool calls\n            for tc in obj.get(\"tool_calls\", []):\n                args = tc.get(\"args\", {})\n                code = args.get(\"CodeContent\") or args.get(\"ReplacementContent\")\n                if code and \"implementation_plan.md\" in args.get(\"TargetFile\", \"\"):\n                    print(f\"Line {idx}: Write/Edit of implementation_plan.md\")\n                    if \"CREATE TABLE\" in code or \"fin_customers\" in code:\n                        print(\"  Found CREATE TABLE / fin_customers in this version!\")\n                        with open(f\"extracted_plan_{idx}.md\", \"w\", encoding=\"utf-8\") as outf:\n                            outf.write(code)\n"